import numpy as np

def test_crossing_rays(grid_list):
    grid = np.array(grid_list)
    height, width = len(grid), len(grid[0])

    wall_row = None
    for r in range(height):
        if np.all(grid[r] == 2):
            wall_row = r
            break

    result = grid.copy()

    for fyr in range(wall_row):
        c_cols = np.where(grid[fyr] == 4)[0]
        if len(c_cols) > 0:
            for fxc in c_cols:
                # Down-right ray
                nr, nc = fyr + 1, fxc + 1
                while nr < wall_row and 0 <= nc < width:
                    if result[nr][nc] == 0:
                        result[nr][nc] = 4
                    nr += 1
                    nc += 1

                # Down-left ray
                nr, nc = fyr + 1, fxc - 1
                while nr < wall_row and nc >= 0:
                    if result[nr][nc] == 0:
                        result[nr][nc] = 4
                    nr += 1
                    nc -= 1

        # Clear original
        if len(c_cols) > 0:
            for fxc in c_cols:
                result[fyr][fxc] = 0

    return result.tolist()

